using System.Text;using System.Text.RegularExpressions;
using MikuMikuLibrary.Archives;using MikuMikuLibrary.Archives.Extensions;using MikuMikuLibrary.Databases;using MikuMikuLibrary.IO;using MikuMikuLibrary.Objects;using MikuMikuLibrary.Textures;
namespace XRomConverter.Target.MegaMix;
internal static class XExclusiveAccessories {
 static Dictionary<string,string> Read(FarcArchive a,string n){using var s=a.Open(n,EntryStreamMode.MemoryStream);using var r=new StreamReader(s);return r.ReadToEnd().TrimStart('\uFEFF').Split('\n').Select(l=>l.TrimEnd('\r')).Where(l=>l.Contains('=')).Select(l=>l.Split('=',2)).ToDictionary(l=>l[0],l=>l[1]);}
 static byte[] Encode(Dictionary<string,string> f)=>Encoding.UTF8.GetBytes(string.Join("\n",f.OrderBy(e=>e.Key,StringComparer.Ordinal).Select(e=>e.Key+"="+e.Value))+"\n");
 static void Save(string path,Dictionary<string,byte[]> entries){using var a=new FarcArchive();foreach(var e in entries)a.Add(e.Key,new MemoryStream(e.Value),false);a.Save(path);}
 public static string? FindEnabled(string gameDirectory){string mods=Path.Combine(gameDirectory,"mods");if(!Directory.Exists(mods))return null;return Directory.GetDirectories(mods).Order().FirstOrDefault(p=>{string config=Path.Combine(p,"config.toml");if(!File.Exists(config))return false;string text=File.ReadAllText(config);return Regex.IsMatch(text,@"(?mi)^\s*enabled\s*=\s*true\s*(?:#.*)?$")&&(Path.GetFileName(p).Equals("PDX accessories",StringComparison.OrdinalIgnoreCase)||Regex.IsMatch(text,@"(?mi)^\s*name\s*=\s*""PDX accessories"""));});}
 public static void RemoveLegacyRegistrations(string root,string reference){
  string rom=Path.Combine(root,"rom");using var rc=BinaryFile.Load<FarcArchive>(Path.Combine(reference,"rom/mod_gm_customize_item_tbl.farc"));var records=Read(rc,"gm_customize_item_id.bin");var ids=records.Where(e=>Regex.IsMatch(e.Key,@"^cstm_item\.\d+\.id$")).Select(e=>e.Value).ToHashSet();
  string customPath=Path.Combine(rom,"mod_gm_customize_item_tbl.farc");Dictionary<string,string> custom;using(var a=BinaryFile.Load<FarcArchive>(customPath))custom=Read(a,"gm_customize_item_id.bin");
  var kept=Enumerable.Range(0,int.Parse(custom["cstm_item.data_list.length"])).Select(i=>$"cstm_item.{i}.").Where(p=>!ids.Contains(custom[p+"id"])).ToArray();var rebuilt=new Dictionary<string,string>{{"cstm_item.data_list.length",kept.Length.ToString()},{"patch","0"},{"version","0"}};
  for(int i=0;i<kept.Length;i++)foreach(var e in custom.Where(e=>e.Key.StartsWith(kept[i],StringComparison.Ordinal)))rebuilt[$"cstm_item.{i}."+e.Key[kept[i].Length..]]=e.Value;Save(customPath,new(){{"gm_customize_item_id.bin",Encode(rebuilt)}});
  string lp=Path.Combine(rom,"lang2/mod_str_array.toml");File.WriteAllLines(lp,File.ReadAllLines(lp).Where(l=>{var m=Regex.Match(l,@"^(?:\w+\.)?(?:customize|cstm_item)\.(\d+)\s*=");return !m.Success||!ids.Contains(m.Groups[1].Value);}),new UTF8Encoding(false));
  using var refItems=BinaryFile.Load<FarcArchive>(Path.Combine(reference,"rom/mod_chritm_prop.farc"));string tablePath=Path.Combine(rom,"mod_chritm_prop.farc");var entries=new Dictionary<string,byte[]>();
  using(var a=BinaryFile.Load<FarcArchive>(tablePath))foreach(var name in a.FileNames){if(!refItems.FileNames.Contains(name)){using var s=a.Open(name,EntryStreamMode.MemoryStream);using var m=new MemoryStream();s.CopyTo(m);entries[name]=m.ToArray();continue;}var f=Read(a,name);var r=Read(refItems,name);var uids=r.Where(e=>e.Key.EndsWith(".data.obj.0.uid")).Select(e=>e.Value).ToHashSet(StringComparer.OrdinalIgnoreCase);var rows=Enumerable.Range(0,int.Parse(f["item.length"])).Select(i=>$"item.{i}.").Where(p=>!uids.Contains(f.GetValueOrDefault(p+"data.obj.0.uid",""))).ToArray();var table=f.Where(e=>!e.Key.StartsWith("item.")).ToDictionary(e=>e.Key,e=>e.Value);for(int i=0;i<rows.Length;i++)foreach(var e in f.Where(e=>e.Key.StartsWith(rows[i],StringComparison.Ordinal)))table[$"item.{i}."+e.Key[rows[i].Length..]]=e.Value;table["item.length"]=rows.Length.ToString();entries[name]=Encode(table);}Save(tablePath,entries);
  var referenceDb=BinaryFile.Load<ObjectDatabase>(Path.Combine(reference,"rom/objset/mod_obj_db.bin"));string dbPath=Path.Combine(rom,"objset/mod_obj_db.bin");var db=BinaryFile.Load<ObjectDatabase>(dbPath);var setNames=referenceDb.ObjectSets.Select(s=>s.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);foreach(var set in db.ObjectSets.Where(s=>setNames.Contains(s.Name)).ToArray())db.ObjectSets.Remove(set);db.Save(dbPath);
  var refs=BinaryFile.Load<SpriteDatabase>(Path.Combine(reference,"rom/2d/mod_spr_db.bin"));string sp=Path.Combine(rom,"2d/mod_spr_db.bin");var sprites=BinaryFile.Load<SpriteDatabase>(sp);var names=refs.SpriteSets.Select(s=>s.Name).ToHashSet();foreach(var set in sprites.SpriteSets.Where(s=>names.Contains(s.Name)).ToArray())sprites.SpriteSets.Remove(set);sprites.Save(sp);
  File.WriteAllLines(Path.Combine(root,"PDX-LEGACY-ICONS-TO-REMOVE.txt"),refs.SpriteSets.Select(s=>"rom/2d/"+Path.ChangeExtension(s.FileName,".farc")));
 }
 public static void Write(string root,string gameDirectory){
  string? reference=FindEnabled(gameDirectory);if(reference==null){Console.WriteLine("[PDX_ACCESSORY_REPLACE] No enabled PDX accessories detected; skipped.");return;}
  string rom=Path.Combine(root,"rom"),folder=Path.Combine(rom,"objset");var db=BinaryFile.Load<ObjectDatabase>(Path.Combine(folder,"mod_obj_db.bin"));var refDb=BinaryFile.Load<ObjectDatabase>(Path.Combine(reference,"rom/objset/mod_obj_db.bin"));using var items=BinaryFile.Load<FarcArchive>(Path.Combine(reference,"rom/mod_chritm_prop.farc"));
  var assets=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var report=new List<string>{"Item\tUIDArcade\tUIDX\tFARC"};
  foreach(var name in items.FileNames){var n=Read(items,name);for(int i=0;i<int.Parse(n["item.length"]);i++){string rp=$"item.{i}.",number=n[rp+"no"],uid=n[rp+"data.obj.0.uid"],set=n[rp+"objset.0"];if(!assets.Add(uid))continue;
   var targetInfo=refDb.ObjectSets.Single(s=>s.Name.Equals(set,StringComparison.OrdinalIgnoreCase));var sourceInfo=db.ObjectSets.Single(s=>s.Objects.Any(o=>o.Name.Equals(uid+"_X",StringComparison.OrdinalIgnoreCase)));
   using var source=BinaryFile.Load<FarcArchive>(Path.Combine(folder,sourceInfo.ArchiveFileName));var objects=source.Open<ObjectSet>(sourceInfo.FileName);var model=objects.Objects.Single(o=>o.Name.Equals(uid+"_X",StringComparison.OrdinalIgnoreCase));var textures=source.Open<TextureSet>(sourceInfo.TextureFileName);if(model.Meshes.Count==0||objects.TextureIds.Count!=textures.Textures.Count)throw new InvalidDataException("Invalid PDX model replacement "+uid);
   objects.Objects.Clear();objects.Objects.Add(model);model.Name=uid.ToLowerInvariant();model.Id=targetInfo.Objects.Single(o=>o.Name.Equals(uid,StringComparison.OrdinalIgnoreCase)).Id;using(var a=new FarcArchive()){a.Add(targetInfo.FileName,objects);a.Add(targetInfo.TextureFileName,textures);a.Save(Path.Combine(folder,targetInfo.ArchiveFileName));}
   string skin=Path.Combine(rom,"skin_param"),skp=Path.Combine(skin,"ext_skp_"+uid.ToLowerInvariant()+"_x.txt");if(File.Exists(skp))File.Copy(skp,Path.Combine(skin,"ext_skp_"+uid.ToLowerInvariant()+".txt"),true);report.Add($"{number}\t{uid}\t{uid}_X\t{targetInfo.ArchiveFileName}");
  }}File.WriteAllLines(ConversionReports.PathFor(root,"X-EXCLUSIVE-ACCESSORIES.tsv"),report);Console.WriteLine($"[PDX_ACCESSORY_REPLACE] Detected {Path.GetFileName(reference)}; {assets.Count} model replaces; menu and translations owned by PDX.");
 }
}
